                "constraint"
              ],
              "rationale": "Die Festlegung auf eine reine Mobile-App ist eine Architekturentscheidung und schränkt betroffene Umsetzungen auf mobile Nutzung ohne Web-Client ein.",
              "targetPbiIds": [
                "PBI-001",
                "PBI-025",
                "PBI-030"
              ]
            },
            {
              "itemId": "ARCH-02",
              "roles": [
                "constraint"
              ],
              "rationale": "Die Priorisierung, dass andere Personen Bewohner besser verstehen sollen, rahmt fachlich das Produktziel und schränkt die Lösungsrichtung dafür ein.",
              "targetPbiIds": [
                "PBI-001"
              ]
            },
            {
              "itemId": "ARCH-03",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Der Kernansatz, Profil- und Kommunikationswissen bereitzustellen, ist eine dokumentierbare Lösungsentscheidung und begrenzt die fachliche Ausgestaltung der Kernfunktionen.",
              "targetPbiIds": [
                "PBI-001",
                "PBI-012",
                "PBI-013",
                "PBI-018"
              ]
            },
            {
              "itemId": "ARCH-04",
              "roles": [
                "constraint"
              ],
              "rationale": "Der ausgeschlossene Lösungsansatz verbietet bidirektionale Individualübersetzung und begrenzt damit die Produkt- und Lösungsdefinition.",
              "targetPbiIds": [
                "PBI-001"
              ]
            },
            {
              "itemId": "ARCH-05",
              "roles": [
                "constraint"
              ],
              "rationale": "Die bestehende Akten- und Dokumentationslage ist ein Rahmen für Funktionen zur Datenübernahme und Dokumentationsintegration.",
              "targetPbiIds": [
                "PBI-027"
              ]
            },
            {
              "itemId": "ARCH-06",
              "roles": [
                "constraint"
              ],
              "rationale": "Die Annahme schwer nutzbarer Akten begründet, dass Datenübernahme und Darstellung schnellen Zugriff statt Aktenersatz unterstützen müssen.",
              "targetPbiIds": [
                "PBI-027"
              ]
            },
            {
              "itemId": "ARCH-07",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Login nur mit intern vergebenen Accounts ohne Selbstregistrierung ist eine klare Architektur- und Sicherheitsentscheidung mit direkter Wirkung auf Account- und Login-Funktionen.",
              "targetPbiIds": [
                "PBI-002",
                "PBI-005"
              ]
            },
            {
              "itemId": "ARCH-08",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Mindestens Admin- und User-Rollen mit klaren Grundrechten sind eine Architekturentscheidung und schränken Rollen- und Accountverwaltung ein.",
              "targetPbiIds": [
                "PBI-002",
                "PBI-003"
              ]
            },
            {
              "itemId": "ARCH-09",
              "roles": [
                "constraint"
              ],
              "rationale": "Der Zugriff für Angehörige mit noch auszuformulierenden Rechten begrenzt das Rechtemodell und die Sichtbarkeit fachlich.",
              "targetPbiIds": [
                "PBI-003"
              ]
            },
            {
              "itemId": "ARCH-10",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Der zusätzliche Bewohner-Account mit stark eingeschränkten Rechten ist eine begründbare Rollenentscheidung und beeinflusst das Rechtemodell sowie zulässige Sicht auf Profile.",
              "targetPbiIds": [
                "PBI-003",
                "PBI-013",
                "PBI-014"
              ]
            },
            {
              "itemId": "ARCH-11",
              "roles": [
